<?php
declare(strict_types=1);
namespace App;
final class FileBackup {
 public const ROOTS=['.local/documents','private/imports','private/auxiliary','private/market','private/market-capture','private/integrations/blobs','private/integrations/capture-archive','private/integrations/state'];
 private static function inventory(string $base,array $roots):array {$out=[];foreach($roots as $root){if(!in_array($root,self::ROOTS,true))throw new \RuntimeException('FILE_BACKUP_ROOT_REJECTED');$path=$base.'/'.$root;if(!file_exists($path))continue;$realRoot=realpath($path);$realBase=realpath($base);if(!$realRoot||!$realBase||!str_starts_with(strtolower(str_replace(chr(92),'/',$realRoot)),strtolower(rtrim(str_replace(chr(92),'/',$realBase),'/').'/')))throw new \RuntimeException('FILE_BACKUP_SOURCE_OUTSIDE_ROOT');if(is_link($path)||!is_dir($path))throw new \RuntimeException('FILE_BACKUP_LINK_REJECTED');$it=new \RecursiveIteratorIterator(new \RecursiveDirectoryIterator($path,\FilesystemIterator::SKIP_DOTS));foreach($it as $f){if($f->isLink()||!$f->isFile())throw new \RuntimeException('FILE_BACKUP_LINK_REJECTED');$name=str_replace('\\','/',substr($f->getPathname(),strlen($base)+1));if(str_contains($name,'..')||str_contains($name,"\0"))throw new \RuntimeException('FILE_BACKUP_PATH_REJECTED');$out[$name]=['bytes'=>$f->getSize(),'sha256'=>hash_file('sha256',$f->getPathname())];}}ksort($out);return $out;}
 public static function create():array {$start=gmdate(DATE_ATOM);$before=self::inventory(APP_ROOT,self::ROOTS);$dir=(StorageBudget::artifactRoot()?:APP_ROOT.'/private').'/backups/files-'.gmdate('Ymd-His').'-'.bin2hex(random_bytes(4));StorageBudget::target($dir,array_sum(array_column($before,'bytes')));if(!mkdir($dir.'/payload',0700,true))throw new \RuntimeException('FILE_BACKUP_CREATE_FAILED');foreach($before as $relative=>$entry){$target=$dir.'/payload/'.$relative;if(!is_dir(dirname($target)))mkdir(dirname($target),0700,true);if(!copy(APP_ROOT.'/'.$relative,$target)||filesize($target)!==$entry['bytes']||!hash_equals($entry['sha256'],hash_file('sha256',$target)))throw new \RuntimeException('FILE_BACKUP_COPY_FAILED');@chmod($target,0600);}if(self::inventory(APP_ROOT,self::ROOTS)!==$before)throw new \RuntimeException('FILE_BACKUP_SOURCE_CHANGED_NO_COMPLETE');$manifest=['version'=>1,'started_at'=>$start,'completed_at'=>gmdate(DATE_ATOM),'roots'=>self::ROOTS,'files'=>$before,'files_count'=>count($before),'bytes'=>array_sum(array_column($before,'bytes')),'global_atomic'=>false,'config_and_key_escrow'=>'separate protected operator procedure; never release payload'];$bytes=json_encode($manifest,JSON_PRETTY_PRINT|JSON_THROW_ON_ERROR);file_put_contents($dir.'/manifest.json',$bytes,LOCK_EX);file_put_contents($dir.'/COMPLETE',hash('sha256',$bytes)."\n",LOCK_EX);return ['directory'=>$dir,'files'=>count($before),'bytes'=>$manifest['bytes'],'manifest_sha256'=>hash('sha256',$bytes),'global_atomic'=>false];}
 public static function restore(string $backup,string $destination):array {$real=realpath($backup);if(!$real||is_link($backup)||!is_file($real.'/COMPLETE')||is_link($real.'/manifest.json'))throw new \RuntimeException('FILE_RESTORE_INCOMPLETE');$raw=file_get_contents($real.'/manifest.json');if(!hash_equals(trim(file_get_contents($real.'/COMPLETE')),hash('sha256',$raw)))throw new \RuntimeException('FILE_RESTORE_MANIFEST_HASH');$m=json_decode($raw,true,512,JSON_THROW_ON_ERROR);if(($m['version']??null)!==1||($m['roots']??[])!==self::ROOTS)throw new \RuntimeException('FILE_RESTORE_SCOPE');StorageBudget::target($destination,array_sum(array_column($m['files'],'bytes')));if(file_exists($destination)){if(is_link($destination)||!is_dir($destination)||iterator_count(new \FilesystemIterator($destination,\FilesystemIterator::SKIP_DOTS)))throw new \RuntimeException('FILE_RESTORE_EMPTY_TARGET_REQUIRED');}elseif(!mkdir($destination,0700,true))throw new \RuntimeException('FILE_RESTORE_CREATE_FAILED');foreach($m['files']as $relative=>$entry){if(!is_string($relative)||str_contains($relative,'..')||str_contains($relative,'\\')||str_starts_with($relative,'/')||str_contains($relative,':'))throw new \RuntimeException('FILE_RESTORE_PATH_REJECTED');$allowed=false;foreach(self::ROOTS as $root)if(str_starts_with($relative,$root.'/'))$allowed=true;if(!$allowed)throw new \RuntimeException('FILE_RESTORE_PATH_REJECTED');$source=$real.'/payload/'.$relative;for($cursor=$source;strlen($cursor)>strlen($real);$cursor=dirname($cursor))if(is_link($cursor))throw new \RuntimeException('FILE_RESTORE_LINK_REJECTED');if(!is_file($source)||filesize($source)!==$entry['bytes']||!hash_equals($entry['sha256'],hash_file('sha256',$source)))throw new \RuntimeException('FILE_RESTORE_PAYLOAD_HASH');$target=$destination.'/'.$relative;if(!is_dir(dirname($target)))mkdir(dirname($target),0700,true);if(!copy($source,$target)||!hash_equals($entry['sha256'],hash_file('sha256',$target)))throw new \RuntimeException('FILE_RESTORE_COPY_FAILED');@chmod($target,0600);}if(self::inventory($destination,self::ROOTS)!==$m['files'])throw new \RuntimeException('FILE_RESTORE_INVENTORY_MISMATCH');return ['restored'=>true,'files'=>count($m['files']),'manifest_sha256'=>hash('sha256',$raw),'global_atomic'=>false];}
}
